from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png').convert('RGB')).astype(float)
# derive brick/table shape from blue saturation; list blue mask runs each row x 0:256
m=(im[:,:,2]>im[:,:,0]*1.13)&(im[:,:,2]>im[:,:,1]*1.04)&(im[:,:,2]>45)
for y in range(80,144,2):
 xs=np.flatnonzero(m[y])
 # contiguous ranges length >3
 runs=[]
 if len(xs):
  st=pr=xs[0]
  for x in xs[1:]:
   if x>pr+1:
    if pr-st>=3:runs.append((st,pr))
    st=x
   pr=x
  if pr-st>=3:runs.append((st,pr))
 print(y,runs)
